<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ApiError } from '../api/client'
import { closeHelpRequest, disbandSquad, getCommunities, getCommunity, resetCommunityBoss, setCommunityNotifications, updateFacility, type CommunitySummary } from '../api/ecosystem'
import PageHeader from '../components/ui/PageHeader.vue'
import UiModal from '../components/ui/UiModal.vue'
import UiState from '../components/ui/UiState.vue'
import UiPagination from '../components/ui/UiPagination.vue'
import { useToast } from '../composables/useToast'

const route=useRoute(),router=useRouter(),toast=useToast()
const platform=ref(String(route.query.platform??'')),items=ref<CommunitySummary[]>([]),total=ref(0),loading=ref(false),error=ref('')
const page=ref(Math.max(1,Number(route.query.page)||1)),limit=ref(20)
const detail=ref<Record<string,any>|null>(null),open=ref(false),tab=ref(String(route.query.panel??'overview')),busy=ref(false)
const operation=reactive({type:'',target:'',reason:'',confirmation:'',level:1,progress:0,updatedAt:''})
async function load(){loading.value=true;error.value='';try{const params=new URLSearchParams({page:String(page.value),limit:String(limit.value)});if(platform.value)params.set('platform',platform.value);const result=await getCommunities(params);items.value=result.items;total.value=result.total}catch(reason){error.value=reason instanceof ApiError?reason.message:'社区列表加载失败'}finally{loading.value=false}}
async function changePage(value:number){page.value=value;await router.replace({query:{...route.query,page:String(value)}});await load()}
async function changeLimit(value:number){limit.value=value;await changePage(1)}
async function changePlatform(){page.value=1;await router.replace({query:{platform:platform.value,page:'1'}});await load()}
async function openCommunity(id:string){open.value=true;detail.value=await getCommunity(id)}
function begin(type:string,target:string,row?:Record<string,any>){operation.type=type;operation.target=target;operation.reason='';operation.confirmation='';if(row){operation.level=Number(row.Level);operation.progress=Number(row.Progress);operation.updatedAt=String(row.UpdatedAt)}}
async function execute(){if(!detail.value||!operation.reason.trim())return toast.error('请填写操作原因');const community=detail.value.community;busy.value=true;try{if(operation.type==='facility')await updateFacility(community.ID,Number(operation.target),{level:operation.level,progress:operation.progress,reason:operation.reason,expected_updated_at:operation.updatedAt});if(operation.type==='boss')await resetCommunityBoss(community.ID,operation.reason,operation.confirmation);if(operation.type==='help')await closeHelpRequest(operation.target,operation.reason);if(operation.type==='squad')await disbandSquad(operation.target,operation.reason,operation.confirmation);if(operation.type==='notifications')await setCommunityNotifications(community.ID,!community.NotificationsEnabled,operation.reason);toast.success('社区操作已完成并写入审计');operation.type='';detail.value=await getCommunity(community.ID);await load()}catch(reason){toast.error(reason instanceof Error?reason.message:'操作失败')}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><PageHeader eyebrow="Communities" title="社群运营" description="官方群、官方频道与 OneBot 群的社区存档彼此隔离，全局宠物存档保持共享。"/>
<div class="filter-bar"><label><span>社区平台</span><select v-model="platform" @change="changePlatform"><option value="">全部</option><option value="onebot">OneBot 群</option><option value="qq_group">官方群</option><option value="qq_guild">官方频道</option></select></label></div>
<UiState v-if="error" tone="error" title="社区列表加载失败" :description="error" action-label="重试" @action="load"/><div v-else class="community-grid"><button v-for="row in items" :key="row.ID" class="community-card" @click="openCommunity(row.ID)"><div><span class="platform-badge">{{row.Platform}} · {{row.SceneType}}</span><strong>{{row.Platform==='qq_guild'?'频道社区':row.Platform==='qq_group'?'官方群社区':'OneBot 群社区'}}</strong><small>技术标识 · …{{String(row.ID).slice(-10)}}</small></div><dl><div><dt>等级</dt><dd>{{row.Level}}</dd></div><div><dt>成员</dt><dd>{{row.member_count}}</dd></div><div><dt>小队</dt><dd>{{row.squad_count}}</dd></div><div><dt>求助</dt><dd>{{row.open_help_count}}</dd></div></dl></button><div v-if="!loading&&!items.length" class="empty-row">暂无社区数据</div></div>
<UiPagination v-if="!error" :page="page" :limit="limit" :total="total" @change="changePage" @update:limit="changeLimit"/>
<UiModal :open="open" title="社区运营详情" size="large" :busy="busy" @close="open=false"><template v-if="detail"><nav class="page-tabs"><button v-for="item in [['overview','概览'],['facilities','设施'],['members','成员'],['squads','小队'],['boss','首领'],['help','求助单'],['votes','故事投票']]" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{item[1]}}</button></nav><div v-if="tab==='overview'" class="ops-panel"><h2>社区概览</h2><p>等级 {{detail.community.Level}} · 建设材料 {{detail.community.Materials}}</p><small>技术标识：{{detail.community.ID}}</small><button class="btn btn-ghost" @click="begin('notifications','')">{{detail.community.NotificationsEnabled?'关闭':'开启'}}社区通知</button></div><div v-if="tab==='facilities'" class="record-list"><div v-for="row in detail.facilities" :key="row.ID"><span><strong>{{row.Name}}</strong><small>等级 {{row.Level}} · 进度 {{row.Progress}}</small></span><button class="btn btn-primary btn-small" @click="begin('facility',String(row.ID),row)">修正</button></div></div><div v-if="tab==='members'" class="record-list"><div v-for="row in detail.members" :key="row.ID"><span><strong>成员 …{{String(row.AccountID||'').slice(-8)}}</strong><small>贡献 {{row.Contribution||0}} · 支援 {{row.RescueCount||0}}</small></span><span class="badge">{{row.Role||'成员'}}</span></div><UiState v-if="!detail.members?.length" title="暂无社区成员" description="成员产生社区行为后会出现在这里。"/></div><div v-if="tab==='votes'" class="record-list"><div v-for="row in detail.votes" :key="row.ID"><span><strong>{{row.SeasonKey||'当前赛季'}} · 选项 {{row.Choice}}</strong><small>玩家 …{{String(row.AccountID||'').slice(-8)}} · {{row.UpdatedAt||row.CreatedAt||''}}</small></span></div><UiState v-if="!detail.votes?.length" title="暂无故事投票" description="玩家提交赛季选择后会显示汇总明细。"/></div><div v-if="tab==='squads'" class="record-list"><div v-for="row in detail.squads" :key="row.ID"><span><strong>{{row.Name}}</strong><small>成员上限 {{row.MaxMembers||'-'}} · 研究 {{row.Research||0}}</small></span><button class="btn btn-danger btn-small" @click="begin('squad',row.ID)">解散</button></div></div><div v-if="tab==='boss'" class="record-list"><div v-for="row in detail.bosses" :key="row.ID"><span><strong>{{row.Name}}</strong><small>{{row.CurrentHP}} / {{row.MaxHP}} 调查难度</small></span><button class="btn btn-danger btn-small" @click="begin('boss',row.ID)">重置周期</button></div></div><div v-if="tab==='help'" class="record-list"><div v-for="row in detail.help_requests" :key="row.Code"><span><strong>{{row.Code}} · {{row.ItemName}}</strong><small>{{row.Fulfilled}} / {{row.Quantity}} · {{row.Status}}</small></span><button v-if="row.Status==='open'" class="btn btn-ghost btn-small" @click="begin('help',row.Code)">关闭</button></div></div><form v-if="operation.type" class="operation-box" @submit.prevent="execute"><strong>影响预览与确认</strong><template v-if="operation.type==='facility'"><label>目标等级<input v-model.number="operation.level" type="number" min="1"/></label><label>目标进度<input v-model.number="operation.progress" type="number" min="0"/></label></template><label>操作原因<textarea v-model="operation.reason" rows="3"/></label><label v-if="operation.type==='boss'||operation.type==='squad'">确认文字<input v-model="operation.confirmation" :placeholder="operation.type==='boss'?'重置首领':'解散小队'"/></label><div class="actions"><button type="button" class="btn btn-ghost" @click="operation.type=''">取消</button><button class="btn btn-danger" :disabled="busy">确认执行</button></div></form></template></UiModal>
</section></template>
<style scoped>.community-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.community-card{padding:16px;border:1px solid var(--border-color);border-radius:var(--radius-card);background:var(--bg-surface);color:inherit;text-align:left;cursor:pointer;min-width:0}.community-card strong{display:block;margin:8px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.community-card dl{display:grid;grid-template-columns:repeat(4,1fr);margin:14px 0 0}.community-card dl div{border-left:1px solid var(--border-color);padding-left:8px}.community-card dl div:first-child{border:0;padding-left:0}.community-card dt{font-size:11px;color:var(--text-muted)}.community-card dd{margin:2px 0 0;font-weight:700}.platform-badge{font-size:11px;color:var(--accent)}.ops-panel{padding:16px;border:1px solid var(--border-color);border-radius:12px}@media(max-width:1000px){.community-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.community-grid{grid-template-columns:1fr}}</style>
